import React, { Fragment, useState } from "react";

const UserForm = () => {
    const [username, setUsername] = useState("");

    return (
        <form>
            <Fragment>
                <label>Username</label>
                <input type="text" name="username"/>
                <label>Age (Years)</label>
                <input type="text" name="age"/>
            </Fragment>
        </form>
    );
}

export default UserForm;
